{
  "permissions": {
    "allow": [
      "Bash(go:*)",
      "Bash(gofmt:*)",
      "Bash(node scripts/verify.mjs:*)",
      "Bash(git status)",
      "Bash(git diff:*)"
    ],
    "deny": [
      "Bash(git reset --hard:*)",
      "Bash(git push --force:*)",
      "Bash(git push -f:*)",
      "Read(./.env)",
      "Read(./.env.local)",
      "Read(./.env.*.local)",
      "Read(./.env.development)",
      "Read(./.env.production)",
      "Read(./.env.staging)",
      "Read(./.env.test)",
      "Bash(cat .env:*)",
      "Bash(cat ./.env:*)",
      "Bash(source .env:*)",
      "Bash(type .env:*)",
      "Bash(more .env:*)",
      "Bash(less .env:*)",
      "Bash(head .env:*)",
      "Bash(tail .env:*)",
      "Bash(nl .env:*)",
      "Bash(strings .env:*)",
      "Bash(Get-Content .env:*)",
      "Bash(gc .env:*)",
      "Bash(env)",
      "Bash(printenv:*)",
      "Bash(set)",
      "Bash(export)",
      "Bash(export -p:*)",
      "Bash(declare -x:*)",
      "Bash(typeset -x:*)",
      "Bash(compgen -e:*)",
      "Bash(Get-ChildItem Env:*)",
      "Bash(gci Env:*)",
      "Bash(ls Env:*)",
      "Bash(dir Env:*)",
      "Bash(Get-Variable:*)",
      "Bash(echo $LINEAR_API_KEY:*)",
      "Bash(echo \"$LINEAR_API_KEY\":*)",
      "Bash(echo ${LINEAR_API_KEY}:*)",
      "Bash(echo $env:LINEAR_API_KEY:*)",
      "Bash(echo $GH_TOKEN:*)",
      "Bash(echo \"$GH_TOKEN\":*)",
      "Bash(echo ${GH_TOKEN}:*)",
      "Bash(echo $env:GH_TOKEN:*)",
      "Bash(python -c:*)",
      "Bash(python3 -c:*)",
      "Bash(uv run python -c:*)",
      "Bash(node -e:*)",
      "Bash(node -p:*)"
    ]
  },
  "enabledPlugins": {},
  "plansDirectory": ".agents/plans",
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Read|Edit|Write|NotebookEdit|Bash|mcp__.*(edit|write|create|apply|read).*",
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.agents/vendor/harness/hooks/protect_paths.mjs"
            ],
            "timeout": 30,
            "statusMessage": "Checking protected paths\u2026"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write|NotebookEdit|mcp__.*(edit|write|create|apply).*",
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.agents/vendor/harness/hooks/format_edited.mjs"
            ],
            "timeout": 120,
            "statusMessage": "Formatting\u2026"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.agents/vendor/harness/hooks/verify.mjs"
            ],
            "timeout": 600,
            "statusMessage": "Verifying Definition of Done\u2026"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.agents/vendor/harness/hooks/codex_session_learnings.mjs",
              "--claude"
            ],
            "timeout": 3,
            "statusMessage": "Distilling session learnings\u2026"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.agents/vendor/harness/hooks/learning_recall.mjs"
            ],
            "timeout": 3,
            "statusMessage": "Recalling relevant learnings"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": [
              "${CLAUDE_PROJECT_DIR}/.agents/vendor/harness/hooks/learning_recall.mjs"
            ],
            "timeout": 3,
            "statusMessage": "Recalling relevant learnings"
          }
        ]
      }
    ]
  }
}
